function frame(now){let dt=Math.min(.033,(now-(frame.last||now))/1000);frame.last=now;if(!gamePaused)update(dt);draw();syncOnline(dt)}requestAnimationFrame(frame);
const remotePlayers=new Map();let peer=null,channel=null,netAccum=0,localShotId=0;
function networkSend(data){if(channel&&channel.readyState==='open')channel.send(JSON.stringify(data))}
const origShoot=shoot;
shoot=function(angle,remote=false){origShoot(angle,remote);if(!remote&&fireCooldown>0){localShotId++;networkSend({type:'shot',id:localShotId,x:player.x,y:player.y,a:angle,w:current})}};
function receivePacket(data){if(data.type==='state'){remotePlayers.set(data.id,{x:data.x,y:data.y,angle:data.a,name:data.name||'PLAYER'});if(data.targets){for(let i=0;i<Math.min(targets.length,data.targets.length);i++){let rt=data.targets[i],t=targets[i];if(rt&&!t.alive&&rt.alive){t.alive=true;t.hp=t.max}if(rt&&!rt.alive)t.alive=false}}}else if(data.type==='shot'){let w=current;current=data.w in weapons?data.w:current;const oldX=player.x,oldY=player.y,oldAngle=player.angle;player.x=data.x;player.y=data.y;shoot(data.a,true);player.x=oldX;player.y=oldY;player.angle=oldAngle;current=w}}
function connectChannel(ch){channel=ch;ch.onopen=()=>{document.getElementById('connStatus').textContent='● CONNECTED — peer-to-peer';toast('PEER CONNECTED')};ch.onclose=()=>{document.getElementById('connStatus').textContent='● OFFLINE — solo arena ready';remotePlayers.clear()};ch.onmessage=e=>{try{receivePacket(JSON.parse(e.data))}catch(_){}}}
function setupPeer(){peer=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});peer.ondatachannel=e=>connectChannel(e.channel);peer.onconnectionstatechange=()=>{if(peer.connectionState==='failed')document.getElementById('connStatus').textContent='● CONNECTION FAILED — try a fresh code'};return peer}
function waitIce(pc){if(pc.iceGatheringState==='complete')return Promise.resolve();return new Promise(resolve=>{let done=()=>{if(pc.iceGatheringState==='complete'){pc.removeEventListener('icegatheringstatechange',done);resolve()}};pc.addEventListener('icegatheringstatechange',done);setTimeout(resolve,9000)})}
const localCode=document.getElementById('localCode'),remoteCode=document.getElementById('remoteCode');
document.getElementById('onlineBtn').onclick=()=>document.getElementById('onlinePanel').classList.toggle('open');document.getElementById('closeOnline').onclick=()=>document.getElementById('onlinePanel').classList.remove('open');
document.getElementById('makeOffer').onclick=async()=>{try{peer?.close();peer=setupPeer();connectChannel(peer.createDataChannel('redline'));await peer.setLocalDescription(await peer.createOffer());document.getElementById('connStatus').textContent='● GATHERING NETWORK ROUTE…';await waitIce(peer);localCode.value=JSON.stringify(peer.localDescription);document.getElementById('connStatus').textContent='● OFFER READY — send code to friend'}catch(e){toast('Could not create offer')}};
document.getElementById('makeAnswer').onclick=async()=>{try{let offer=JSON.parse(remoteCode.value);peer?.close();peer=setupPeer();await peer.setRemoteDescription(offer);await peer.setLocalDescription(await peer.createAnswer());document.getElementById('connStatus').textContent='● GATHERING NETWORK ROUTE…';await waitIce(peer);localCode.value=JSON.stringify(peer.localDescription);document.getElementById('connStatus').textContent='● ANSWER READY — send it to host'}catch(e){toast('Paste a valid host offer first')}};
document.getElementById('applyCode').onclick=async()=>{try{await peer.setRemoteDescription(JSON.parse(remoteCode.value));document.getElementById('connStatus').textContent='● CONNECTING…'}catch(e){toast('Invalid remote code — check the copied text')}};
document.getElementById('copyCode').onclick=async()=>{try{await navigator.clipboard.writeText(localCode.value);toast('CONNECTION CODE COPIED')}catch(e){localCode.select();document.execCommand('copy');toast('CONNECTION CODE COPIED')}};
function syncOnline(dt){netAccum+=dt;if(netAccum<.09)return;netAccum=0;if(channel?.readyState==='open')networkSend({type:'state',id:'peer',x:player.x,y:player.y,a:player.angle,targets:targets.map(t=>({alive:t.alive}))})}
addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='1')switchWeapon('pistol');if(k==='2')switchWeapon('ak');if(k==='3')switchWeapon('spas');if(k==='r')reload();if(k===' '&&player.dashCd<=0){player.dash=.18;player.dashCd=1.1;player.x=clamp(player.x+Math.cos(player.angle)*54,35,world.w-35);player.y=clamp(player.y+Math.sin(player.angle)*54,35,world.h-35)}});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('pointermove',e=>{mouse.x=e.clientX;mouse.y=e.clientY});canvas.addEventListener('pointerdown',e=>{if(e.button===0){mouse.down=true;mouse.x=e.clientX;mouse.y=e.clientY}});addEventListener('pointerup',()=>mouse.down=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());
document.querySelectorAll('.weapon').forEach(b=>b.onclick=()=>switchWeapon(b.dataset.weapon));document.getElementById('resetBtn').onclick=reset;
let stick=document.getElementById('stick'),nub=document.getElementById('nub'),stickPointer=null;stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(stickPointer===e.pointerId)moveStick(e)});function moveStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.min(39,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);nub.style.transform=`translate(${Math.cos(a)*m}px,${Math.sin(a)*m}px)`;touchMove.x=Math.cos(a)*m/39;touchMove.y=Math.sin(a)*m/39}function resetStick(){stickPointer=null;touchMove={x:0,y:0};nub.style.transform=''}stick.addEventListener('pointerup',resetStick);stick.addEventListener('pointercancel',resetStick);
let fireButton=document.getElementById('touchFire');fireButton.addEventListener('pointerdown',e=>{touchFiring=true;fireButton.setPointerCapture(e.pointerId)});fireButton.addEventListener('pointerup',()=>touchFiring=false);fireButton.addEventListener('pointercancel',()=>touchFiring=false);document.getElementById('touchReload').onclick=reload;document.getElementById('touchChange').onclick=()=>switchWeapon(current==='pistol'?'ak':current==='ak'?'spas':'pistol');document.getElementById('touchJump').onclick=()=>{if(player.dashCd<=0){player.dash=.18;player.dashCd=1.1;player.x=clamp(player.x+Math.cos(player.angle)*54,35,world.w-35);player.y=clamp(player.y+Math.sin(player.angle)*54,35,world.h-35)}};
})();
</script></body></html>

